"use strict";

const assert = require("assert");
const fs = require("fs");
const Module = require("module");
const path = require("path");

const vaultRoot = path.resolve(
    __dirname,
    "../../../../.."
);

function read(relativePath) {
    return fs.readFileSync(
        path.join(vaultRoot, relativePath),
        "utf8"
    );
}

const mainPath = path.join(
    vaultRoot,
    ".obsidian/plugins/hub-project-menu/main.js"
);

const sourcePath = path.join(
    vaultRoot,
    ".obsidian/plugins/hub-project-menu/plugin.js"
);

const mainSource = read(
    ".obsidian/plugins/hub-project-menu/main.js"
);

new Function(mainSource);
new Function(fs.readFileSync(sourcePath, "utf8"));

assert.ok(
    mainSource.includes("Generated by build.js")
);
assert.doesNotMatch(
    mainSource,
    /require\(\s*["']\.\.?\//
);

const AsyncFunction = Object.getPrototypeOf(
    async function () {}
).constructor;

new AsyncFunction(read("System/Dashboards/Home/view.js"));
new AsyncFunction(read("System/Dashboards/Project/view.js"));

const originalLoad = Module._load;

Module._load = function (request) {
    if (request === "obsidian") {
        class ObsidianBase {}

        return {
            Plugin: ObsidianBase,
            Menu: ObsidianBase,
            Notice: ObsidianBase,
            Modal: ObsidianBase,
            FuzzySuggestModal: ObsidianBase,
            TFile: ObsidianBase,
            TFolder: ObsidianBase,
            normalizePath: value => value,
            setIcon() {}
        };
    }

    return originalLoad.apply(this, arguments);
};

try {
    delete require.cache[require.resolve(mainPath)];
    const HubPlugin = require(mainPath);

    assert.strictEqual(typeof HubPlugin, "function");
} finally {
    Module._load = originalLoad;
}

console.log("Hub plugin load checks passed.");
